package dev.hybridmail;
import org.junit.*;import static org.junit.Assert.*;
import java.nio.file.*;import java.security.*;import java.util.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.bouncycastle.jce.provider.BouncyCastleProvider;
public class SoftwareLevel5OpenPgpTest {
 private static android.view.View find(android.view.View v,String text){if(v instanceof android.widget.TextView t&&t.getText().toString().contains(text))return v;if(v instanceof android.view.ViewGroup g)for(int i=0;i<g.getChildCount();i++){var found=find(g.getChildAt(i),text);if(found!=null)return found;}return null;}
 private void checkUi(Identity id)throws Exception{var in=InstrumentationRegistry.getInstrumentation();MainActivity[] existing={null};in.runOnMainSync(()->{for(var stage:androidx.test.runner.lifecycle.Stage.values())if(stage!=androidx.test.runner.lifecycle.Stage.DESTROYED)for(var candidate:androidx.test.runner.lifecycle.ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(stage))if(candidate instanceof MainActivity main&&!main.isFinishing())existing[0]=main;});var a=existing[0]!=null?existing[0]:(MainActivity)in.startActivitySync(new android.content.Intent(in.getTargetContext(),MainActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));try{in.runOnMainSync(()->{try{for(var entry:Map.<String,Object>of("identity",id,"selected",new AndroidStore.Entry("synthetic","Synthetic", "synthetic.vault.p12",0,"",""),"from","test@example.test","to","test@example.test").entrySet()){var f=MainActivity.class.getDeclaredField(entry.getKey());f.setAccessible(true);f.set(a,entry.getValue());}var method=MainActivity.class.getDeclaredMethod("compose");method.setAccessible(true);method.invoke(a);var format=(android.widget.CheckBox)find(a.findViewById(android.R.id.content),"Use hybrid PQ OpenPGP");assertNotNull(format);assertTrue(format.isEnabled());assertTrue(format.isChecked());method=MainActivity.class.getDeclaredMethod("openPgpKeys");method.setAccessible(true);method.invoke(a);assertNotNull(find(a.findViewById(android.R.id.content),"Export v4 P-521 + hybrid"));assertNotNull(find(a.findViewById(android.R.id.content),"Export v4 P-521 classical"));}catch(Exception e){throw new AssertionError(e);}});}finally{in.runOnMainSync(a::finish);}}
 @Before public void providers(){Security.removeProvider("BC");Security.insertProviderAt(new BouncyCastleProvider(),1);MailEngine.init();}
 @Test public void officialRfc9980Level5Signature()throws Exception{
  var assets=InstrumentationRegistry.getInstrumentation().getContext().getAssets();byte[] cert,sig;try(var in=assets.open("rfc9980-level5/public.asc")){cert=in.readAllBytes();}try(var in=assets.open("rfc9980-level5/signature.asc")){sig=in.readAllBytes();}
  var own=new OpenPgp.PublicIdentity(cert);assertEquals("0d7a8be1410cd68eed4845ab487b4b4cfaecd8ebad1a1166a84230499200ee20",own.fingerprint());assertEquals(36,own.subkey[5]);new LegacyOpenPgp(own.encoded,6).verify(OpenPgp.unarmor(sig,"SIGNATURE"),"Testing\n".getBytes());
 }
 @Test public void vaultAndAllThreeCertificates()throws Exception{
  Path root=Files.createTempDirectory(InstrumentationRegistry.getInstrumentation().getTargetContext().getCacheDir().toPath(),"pgp5-test");var vault=new PrfVault(root.resolve("vault.json"));byte[] prf=PrfVault.random(32);vault.create("YWJj",PrfVault.random(32),prf);
  try{
   var ids=SoftwareIdentityVault.addLevel5OpenPgp(Identity.generateSoftwareProfile("test@example.test",TokenProfile.values()[2],List.of("alias@example.test")));var id=ids.get(1);assertNotNull(id.softwareOpenPgp());var own=OpenPgp.loadOwn(root,id);assertEquals(31,own.primary[5]);assertTrue(own.separated());assertFalse(Arrays.equals(own.primary,own.signingBody()));assertEquals(36,own.subkey[5]);assertTrue(own.quantumEncryption());assertEquals(2,own.certifiedEmails().size());
   var full=own.compatibility;var fallback=OpenPgp.classicalOnlyCompatibility(full);assertEquals(19,full.primary[5]);assertEquals(35,full.subkey[5]);assertEquals(10,fallback.subkey[fallback.subkey.length-2]);assertEquals(9,fallback.subkey[fallback.subkey.length-1]);assertEquals("ECDSA P-521",full.signingAlgorithms());assertEquals("ECDH P-521",fallback.encryptionAlgorithm());assertTrue(full.quantumEncryption());assertFalse(fallback.quantumEncryption());assertEquals(full.fingerprint(),fallback.fingerprint());
   Path saved=root.resolve("identity.vault.p12");SoftwareIdentityVault.save(ids,saved,vault);vault.close();try{SoftwareIdentityVault.load(saved,vault);fail();}catch(IllegalStateException expected){}
   vault=new PrfVault(root.resolve("vault.json"));vault.unlock("YWJj",prf);ids=SoftwareIdentityVault.load(saved,vault);id=ids.get(1);assertEquals(own.fingerprint(),id.softwareOpenPgp().own().fingerprint());assertEquals(full.fingerprint(),id.softwareOpenPgp().own().compatibility.fingerprint());
   for(var recipient:List.of(own,full,fallback))for(boolean encrypted:new boolean[]{false,true}){
    byte[] message=OpenPgp.composeForRecipient(id,own,recipient,encrypted,"test@example.test","test@example.test","Synthetic vault test","Level 5 round trip",null);
    var signer=recipient.version()==6?own:full;var opened=OpenPgp.open(message,signer,own,id,null);assertTrue(opened.text().contains("Level 5 round trip"));assertEquals(encrypted,opened.encrypted());assertTrue(opened.fromMatches());assertEquals(recipient.version()==6,opened.postQuantum());
    if(!encrypted){var parts=OpenPgp.parts(message);byte[] signature=OpenPgp.unarmor(OpenPgp.decoded(OpenPgp.mime(parts.second())),"SIGNATURE");for(int offset:recipient.version()==6?new int[]{1,4741}:new int[]{1}){byte[] bad=signature.clone();bad[bad.length-offset]^=1;try{new LegacyOpenPgp(signer.encoded,signer.version()).verify(bad,parts.first());fail("Corrupted signature accepted");}catch(Exception expected){}}}
   }
   byte[] sealed=OpenPgp.compose(id,own,own,"test@example.test","test@example.test","Tamper","test",null);var parts=OpenPgp.parts(sealed);byte[] bad=OpenPgp.unarmor(OpenPgp.decoded(OpenPgp.mime(parts.second())),"MESSAGE");bad[bad.length-1]^=1;try{id.softwareOpenPgp().decrypt(bad);fail("Tampered encryption accepted");}catch(Exception expected){}
   char[] pass="portable-level5-password".toCharArray();Path backup=root.resolve("backup.p12");Files.write(backup,SoftwareIdentityVault.export(saved,vault,pass));var portable=Identity.loadProfiles(backup,pass);assertEquals(own.fingerprint(),portable.get(1).softwareOpenPgp().own().fingerprint());assertEquals(full.fingerprint(),portable.get(1).softwareOpenPgp().own().compatibility.fingerprint());
   byte[] transfer=IdentityTransfer.create(ids,"YWJj",PrfVault.random(32),prf,root);var transferred=IdentityTransfer.open(transfer,"YWJj",prf,root);assertEquals(own.fingerprint(),transferred.get(1).softwareOpenPgp().own().fingerprint());assertEquals(full.fingerprint(),transferred.get(1).softwareOpenPgp().own().compatibility.fingerprint());try{IdentityTransfer.open(transfer,"YWJj",PrfVault.random(32),root);fail("Wrong passkey output accepted");}catch(Exception expected){}
   var restored=portable.get(1);checkUi(restored);var message=OpenPgp.compose(restored,own,own,"test@example.test","test@example.test","Export test","portable",null);assertTrue(OpenPgp.open(message,own,own,restored,null).text().contains("portable"));
  }finally{vault.close();Arrays.fill(prf,(byte)0);try(var paths=Files.walk(root)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
 }
}
